import json, collections

def load(path):
    with open(path) as f:
        return json.load(f, object_pairs_hook=collections.OrderedDict)

def dump(path, data):
    with open(path, 'w') as f:
        json.dump(data, f, indent=2)
        f.write('\n')

for path in ['marketplace.json', '.claude-plugin/marketplace.json']:
